import csv,collections,re
from decimal import Decimal
B="C:/Users/pedro/OneDrive/Área de Trabalho/ITA_projects/Hackaton/saida/checkouts/"
def rd(n):
    with open(B+n,encoding='utf-8',newline='') as f: return list(csv.DictReader(f,delimiter=';'))
com=rd('comissoes_por_lojista.csv'); div=rd('divergencias_taxa.csv'); pen=rd('pendencias.csv'); ras=rd('rastro.csv')
print('cols', list(com[0].keys())); print('cols', list(div[0].keys())); print('cols', list(pen[0].keys())); print('cols', list(ras[0].keys()))
# rastro sums
s=collections.defaultdict(Decimal); n=collections.Counter()
for r in ras: s[r['id_saida']]+=Decimal(r['valor']); n[r['id_saida']]+=1
bad=[]
for c in com:
    if s[c['id_saida']]!=Decimal(c['comissao_brl']): bad.append(('com',c['id_saida'],s[c['id_saida']],c['comissao_brl']))
for d in div:
    if s[d['id_saida']]!=Decimal(d['diferenca_brl']): bad.append(('div',d['id_saida'],s[d['id_saida']],d['diferenca_brl']))
for p in pen:
    if s[p['id_saida']]!=Decimal(p['valor_brl']): bad.append(('pen',p['id_saida'],s[p['id_saida']],p['valor_brl']))
print('rastro mismatches', bad)
print('rastro linhas por comissao', {c['cnpj']:n[c['id_saida']] for c in com})
print('ids rastro sem saida', set(s)-set(c['id_saida'] for c in com+div+pen))
print('total rastro linhas', len(ras), 'ids unicos origem nao vazios', len(set(r['ref_origem'] for r in ras)))
# formato
bad_fmt=[]
for name,rows in [('com',com),('div',div),('pen',pen)]:
    for r in rows:
        for k,v in r.items():
            if k in('cnpj',) and not re.fullmatch(r'\d{14}',v or ''): bad_fmt.append((name,k,v))
            if k in('comissao_brl','diferenca_brl','valor_brl','valor','taxa_contratada_pct','taxa_aplicada_pct') and v and not re.fullmatch(r'-?\d+(\.\d+)?',v): bad_fmt.append((name,k,v))
print('fmt issues', bad_fmt[:10], len(bad_fmt))
print('total comissao', sum(Decimal(c['comissao_brl']) for c in com))
print('total divergencia', sum(Decimal(d['diferenca_brl']) for d in div), len(div))
print('ids duplicados div', len(div)-len(set(d['id_saida'] for d in div)))
print('pendencias', [(p['tipo'],p['valor_brl'],p['quem_decide']) for p in pen])
EOF

